static int SumToRecursive(int n)
{
    if (n <= 0) return 0;                 // base case
    return n + SumToRecursive(n - 1);     // recursive case
}

static int SumToLoop(int n)
{
    int total = 0;
    for (int i = 1; i <= n; i++) total += i;
    return total;
}

