static int GcdLoop(int a, int b)
{
    while (b != 0)
    {
        int remainder = a % b;
        a = b;
        b = remainder;
    }
    return a;
}

static int GcdRecursive(int a, int b)
{
    if (b == 0) return a;               // base case
    return GcdRecursive(b, a % b);      // smaller: the remainder is less than b
}

