class SmallStack
{
    private int[] items = new int[4];
    private int count;

    public int Count => count;

    public void Push(int value)
    {
        if (count == items.Length)
        {
            throw new InvalidOperationException("Stack is full.");
        }

        items[count] = value;
        count++;
    }

    public int Pop()
    {
        if (count == 0)
        {
            throw new InvalidOperationException("Stack is empty.");
        }

        count--;
        return items[count];
    }
}

