static int[] Gaps(int n, int multiplier) {
    List<int> gaps = new List<int>();
    for (int h = 1; h < n;) {
        gaps.Add(h);
        if (h > (n - 2) / multiplier) break;
        h = multiplier * h + 1;
    }
    gaps.Reverse(); return gaps.ToArray();
}
static int[] PowerTwoGaps(int n) {
    List<int> gaps = new List<int>();
    for (int h = 1; h < n;) {
        gaps.Add(h); if (h > (n - 1) / 2) break; h *= 2;
    }
    gaps.Reverse(); return gaps.ToArray();
}
static void ShellSort(int[] data, int[] gaps) {
    foreach (int gap in gaps)
        for (int j = gap; j < data.Length; j++) {
            int value = data[j], i = j;
            while (i >= gap && data[i - gap] > value) { data[i] = data[i - gap]; i -= gap; }
            data[i] = value;
        }
}
